inline void index_svg_definitions(flight::Ref<XmlElement> root, flight::Ref<SvgImportContext> context) {
  std::function<void(flight::Ref<XmlElement>, std::optional<flight::Ref<XmlElement>>)> index_element = [=](flight::Ref<XmlElement> element, std::optional<flight::Ref<XmlElement>> parent) {
  context->parent_by_element.set(element, parent);
  const std::optional<flight::String> id = attribute(element, flight::String("id"));
  if (id.has_value()) {
    context->elements_by_id.set(id.value(), element);
  }
  for (auto child : element->children) {
    index_element(child, std::optional<flight::Ref<XmlElement>>{element});
  }
};
  index_element(root, std::nullopt);
  visit_xml_elements(root, [=](flight::Ref<XmlElement> element) {
  const flight::String name = local_name(element->name);
  const std::optional<flight::String> id = attribute(element, flight::String("id"));
  if ((id.has_value() && ((name == flight::String("linearGradient")) || (name == flight::String("radialGradient"))))) {
    auto gradient = parse_svg_gradient(element, context);
    if (gradient.has_value()) {
      context->gradients_by_id.set(id.value(), gradient.value());
    }
  }
});
}

